const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  BorderStyle, TabStopType, convertMillimetersToTwip
} = require("docx");
const fs = require("fs");

const JP = "Yu Mincho";
const JPG = "Yu Gothic";

// helper: section heading (gothic, bold, small leading rule feel)
function heading(text) {
  return new Paragraph({
    spacing: { before: 140, after: 40 },
    children: [new TextRun({ text, bold: true, size: 21, font: JPG })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "444444", space: 2 } },
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.BOTH,
    spacing: { line: 300, after: opts.after ?? 20 },
    indent: opts.noIndent ? undefined : { firstLine: 200 },
    children: [new TextRun({ text, size: 19, font: JP })],
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "b", level: 0 },
    spacing: { line: 290, after: 10 },
    children: [new TextRun({ text, size: 19, font: JP })],
  });
}

const doc = new Document({
  numbering: {
    config: [{
      reference: "b",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "・",
        style: { paragraph: { indent: { left: 340, hanging: 220 } } },
      }],
    }],
  },
  styles: {
    default: {
      document: { run: { font: JP, size: 19 } },
    },
  },
  sections: [{
    properties: {
      page: {
        margin: {
          top: convertMillimetersToTwip(18),
          bottom: convertMillimetersToTwip(16),
          left: convertMillimetersToTwip(20),
          right: convertMillimetersToTwip(20),
        },
        // A4 is docx-js default
      },
    },
    children: [
      // Header line: 研究報告書
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 40 },
        children: [new TextRun({ text: "研究報告書", size: 22, font: JPG, bold: true })],
      }),
      // Title
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 30 },
        children: [new TextRun({
          text: "ハーフミラーを用いたミラー反転式立体ディスプレイによる",
          size: 26, font: JPG, bold: true,
        })],
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 60 },
        children: [new TextRun({
          text: "HMD非装着型の接触可能なAR/VR体験の実現",
          size: 26, font: JPG, bold: true,
        })],
      }),
      // Name / affiliation (placeholders)
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        spacing: { after: 60 },
        children: [new TextRun({ text: "所属:〔大学・学部・学科名〕　氏名:〔氏名〕", size: 19, font: JP })],
      }),

      heading("1. 研究背景と目的"),
      body("AR/VRにおいて仮想物体に「触れる」体験は没入感の中核をなすが、一般にヘッドマウントディスプレイ(HMD)の装着を要し、装着に伴う身体的不快感や、視界の遮蔽による対人コミュニケーションの阻害が課題となっている。本研究では、HMDを装着せずに裸眼で立体映像を観察でき、かつ映像に実際に手を差し入れて触れられるインタラクティブディスプレイの実現を目的とする。"),

      heading("2. 提案システム"),
      body("ディスプレイを45度傾けて設置し、水平に配置したハーフミラーへ映像を反射させるペッパーズゴースト方式を採用した。映像はハーフミラー上方の空中に浮かんで知覚され、その空間にはディスプレイ面という物理的障壁が存在しないため、ユーザーは映像の提示位置に直接手を差し入れることができる。コンテンツとして水槽に浮かぶカエルの3Dモデルを提示し、以下の要素技術をUnity上で統合した。"),
      bullet("視点追従立体表示(Fish Tank VR):Webカメラの顔検出に基づき投影行列を毎フレーム計算するオフアクシス投影を自前実装し、頭部位置に応じた運動視差を提示。顔の奥行きに応じた遠近感の強調も行う。"),
      bullet("接触変形:接触点の法線方向へメッシュを押し込む変形処理を自作し、触れた際の視覚的フィードバックを実現。入力ソースと変形処理を分離した設計とし、後述のハンドトラッキング接続に備えた。"),
      bullet("空間音響:HRTFによる立体音響(Steam Audio)を導入し、顔の向きによる定位変化、顔とスクリーンの距離に応じた音量変化を実装。距離推定は顔のバウンディングボックスと向きの補正により頑健化した。"),
      bullet("ミラー反転対応:ハーフミラーによる鏡像反転を打ち消すため、投影行列のY軸反転・カリング補正・UI反転を一括して切り替える反転システムを実装した。"),
      bullet("キャリブレーションUI:5点キャリブレーションに距離・顔向き・顔サイズの較正を統合し、設置環境ごとの調整を可能にした。"),

      heading("3. 現在の進捗と課題"),
      body("上記の各機能は実装・動作確認済みであり、現在は接触入力を暫定のマウス操作からハンドトラッキングセンサ(Leap Motion)へ置き換える統合作業に取り組んでいる。センサを装置内に特殊な角度で設置する構成のため、座標系の回転補正を実機で追い込む必要があるほか、トラッキングソフトウェアとゲームエンジン側プラグインのバージョン互換性の問題が生じており、動作検証済みの版数の組合せへ揃える方針で解決を進めている。"),

      heading("4. 今後の計画"),
      body("ハンドトラッキング統合の完了後、実手と仮想物体の接触インタラクションを完成させ、SUS・NASA-TLX・Presence Questionnaireを用いた評価実験(10〜11月実施予定)により、HMD型との比較を含めた提案システムの有効性を検証する。"),

      // Figure placeholder
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 10 },
        border: {
          top: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 6 },
          bottom: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 6 },
          left: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 6 },
          right: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 6 },
        },
        children: [new TextRun({ text: "〔図1:装置写真を挿入(下記参照)〕", size: 19, font: JP, color: "888888" })],
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 20 },
        children: [new TextRun({ text: "図1　提案システムの外観と体験の様子", size: 18, font: JP })],
      }),
    ],
  }],
});

Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync("/home/claude/report/研究報告書.docx", buf);
  console.log("written");
});

