const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  BorderStyle, SectionType, convertMillimetersToTwip
} = require("docx");
const fs = require("fs");

const JP = "Yu Mincho";
const JPG = "Yu Gothic";

function heading(num, text) {
  return new Paragraph({
    spacing: { before: 120, after: 40 },
    children: [new TextRun({ text: `${num}．${text}`, bold: true, size: 20, font: JPG })],
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.BOTH,
    spacing: { line: 270, after: opts.after ?? 10 },
    indent: opts.noIndent ? undefined : { firstLine: 180 },
    children: [new TextRun({ text, size: 18, font: JP })],
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "b", level: 0 },
    alignment: AlignmentType.BOTH,
    spacing: { line: 260, after: 6 },
    children: [new TextRun({ text, size: 18, font: JP })],
  });
}

function figBox(label) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 60, after: 6 },
    border: {
      top: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 10 },
      bottom: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 10 },
      left: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 4 },
      right: { style: BorderStyle.DASHED, size: 4, color: "999999", space: 4 },
    },
    children: [new TextRun({ text: label, size: 17, font: JP, color: "888888" })],
  });
}

function caption(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 40 },
    children: [new TextRun({ text, size: 16, font: JP })],
  });
}

const margin = {
  top: convertMillimetersToTwip(16),
  bottom: convertMillimetersToTwip(14),
  left: convertMillimetersToTwip(18),
  right: convertMillimetersToTwip(18),
};

const doc = new Document({
  numbering: {
    config: [{
      reference: "b",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "・",
        style: { paragraph: { indent: { left: 300, hanging: 200 } } },
      }],
    }],
  },
  styles: { default: { document: { run: { font: JP, size: 18 } } } },
  sections: [
    // ===== Section 1: full-width header/title =====
    {
      properties: { page: { margin } },
      children: [
        new Paragraph({
          alignment: AlignmentType.RIGHT,
          spacing: { after: 10 },
          children: [new TextRun({ text: "研究報告書", size: 19, font: JPG })],
        }),
        new Paragraph({
          alignment: AlignmentType.RIGHT,
          spacing: { after: 60 },
          border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: "000000", space: 4 } },
          children: [new TextRun({ text: "〔所属研究室名〕　〔氏名〕", size: 19, font: JPG })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 20 },
          children: [new TextRun({
            text: "ハーフミラーを用いたミラー反転式立体ディスプレイによる",
            size: 25, font: JPG, bold: true,
          })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 40 },
          children: [new TextRun({
            text: "HMD非装着型の接触可能なAR/VR体験の実現",
            size: 25, font: JPG, bold: true,
          })],
        }),
      ],
    },
    // ===== Section 2: two-column body =====
    {
      properties: {
        type: SectionType.CONTINUOUS,
        page: { margin },
        column: { count: 2, space: convertMillimetersToTwip(7) },
      },
      children: [
        heading("1", "研究背景"),
        body("AR/VRにおいて仮想物体に「触れる」体験は没入感の中核をなす。しかし一般にヘッドマウントディスプレイ(HMD)の装着が前提となっており、装着に伴う身体的不快感や、視界の遮蔽による周囲との対人コミュニケーションの阻害が課題として指摘されている。一方、ソニーELF-SR2に代表される裸眼立体ディスプレイは装着不要だが、ディスプレイ面という物理的障壁があるため映像に直接触れることはできない。"),

        heading("2", "研究目的"),
        body("本研究は、HMDを装着せず裸眼で立体映像を観察でき、かつ映像の提示位置に実際に手を差し入れて触れられるインタラクティブディスプレイを構築し、装着負担のないAR/VR体験を実現することを目的とする。"),

        heading("3", "進捗報告"),
        body("ディスプレイを45度傾けて設置し、水平に配置したハーフミラーへ映像を反射させるペッパーズゴースト方式の装置を製作した(図1)。映像はハーフミラー上方の空中に浮かんで知覚され、その空間には物理的障壁が存在しないため、ユーザーは映像に直接手を差し入れられる。コンテンツとして水槽に浮かぶカエルの3Dモデルを提示し、以下の要素技術をUnity上で実装・統合した。"),
        bullet("視点追従立体表示(Fish Tank VR):Webカメラの顔検出に基づくオフアクシス投影を自前実装し、頭部位置に応じた運動視差を提示。顔の奥行きに応じた遠近感の強調も行う。"),
        bullet("接触変形:接触点の法線方向へメッシュを押し込む変形処理を自作し、触れた際の視覚的フィードバックを実現。入力ソースと変形処理を分離した設計とした。"),
        bullet("空間音響:HRTFによる立体音響を導入し、顔の向きによる定位変化、顔とスクリーンの距離に応じた音量変化を実装した。"),
        bullet("ミラー反転対応:鏡像反転を打ち消すため、投影行列のY軸反転・カリング補正・UI反転を一括で切り替える反転システムを実装した。"),
        bullet("キャリブレーションUI:5点較正に距離・顔向き・顔サイズの較正を統合し、設置環境ごとの調整を可能にした。"),
        figBox("〔図1:装置外観・体験の様子の写真〕"),
        caption("図1　提案システムの外観と体験の様子"),
        body("現在は、接触入力を暫定のマウス操作からハンドトラッキングセンサ(Leap Motion)へ置き換える統合作業に取り組んでいる。センサを装置内へ特殊な角度で設置する構成のため座標系の回転補正を実機で検証する必要があるほか、トラッキングソフトウェアとプラグインのバージョン互換性の問題を特定しており、動作検証済みの版数の組合せへ揃える方針で解決を進めている。"),

        heading("4", "今後の研究活動"),
