const JP = "Yu Mincho";
const JPG = "Yu Gothic";

function heading(num, text) {
  return new Paragraph({
    spacing: { before: 120, after: 40 },
    children: [new TextRun({ text: `${num}．${text}`, bold: true, size: 20, font: JPG })],
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    alignment: AlignmentType.BOTH,
    spacing: { line: 270, after: opts.after ?? 10 },
    indent: opts.noIndent ? undefined : { firstLine: 180 },
    children: [new TextRun({ text, size: 18, font: JP })],
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "b", level: 0 },
    alignment: AlignmentType.BOTH,
    spacing: { line: 260, after: 6 },
    children: [new TextRun({ text, size: 18, font: JP })],
