    </div>
    <div class="text-result">
      <div class="label-row">
        <span>説明文</span>
        <button class="copy-btn" id="copyDescBtn">コピー</button>
      </div>
      <div class="content" id="outDesc"></div>
    </div>
  </section>

  <!-- 4. 出力：めくり -->
  <section>
    <div class="section-label">
