<div class="toast" id="toast"></div>

<script>
const STORAGE_KEY = 'netamise:lastPerformers';
let performers = [];
let idSeed = 0;

function newRow(name='', url=''){
  return { id: 'p'+(idSeed++), name, url };
}

function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._timer);
  t._timer = setTimeout(()=> t.classList.remove('show'), 1800);
}

/* ---------- 出演者リスト描画 ---------- */
function renderPerformerList(){
  const wrap = document.getElementById('performerList');
  wrap.innerHTML = '';
  performers.forEach((p, i) => {
    const row = document.createElement('div');
    row.className = 'performer-row';
    row.innerHTML = `
      <div class="order">${i+1}</div>
      <input type="text" placeholder="名前" data-field="name" value="${escapeAttr(p.name)}">
      <input type="text" placeholder="https://youtu.be/..." data-field="url" value="${escapeAttr(p.url)}">
      <button class="icon-btn" data-action="remove" title="削除">×</button>
    `;
    row.querySelectorAll('input').forEach(inp => {
      inp.addEventListener('input', () => {
        p[inp.dataset.field] = inp.value;
        renderOutputs();
        persist();
      });
    });
    row.querySelector('[data-action=remove]').addEventListener('click', () => {
      performers = performers.filter(x => x.id !== p.id);
      renderPerformerList();
      renderOutputs();
      persist();
    });
    wrap.appendChild(row);
  });
}

function escapeAttr(s){
  return (s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;');
}
function escapeHtml(s){
  return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

/* ---------- 出力（タイトル・説明文・めくり） ---------- */
function renderOutputs(){
  const date = document.getElementById('eventDate').value.trim();
  const title = date ? `${date} ネタ見せちゃん` : '';
  document.getElementById('formTitle').value = title;
  document.getElementById('outTitle').textContent = title || '（開催日を入力すると表示されます）';
  document.getElementById('outDesc').textContent = document.getElementById('formDesc').value;

  const grid = document.getElementById('ticketGrid');
  const valid = performers.filter(p => p.name.trim());
  if(valid.length === 0){
    grid.innerHTML = '<div class="empty-state">出演者を1組以上入力すると、ここにめくりが並びます</div>';
    return;
  }
  grid.innerHTML = '';
  valid.forEach((p, i) => {
    const ticket = document.createElement('div');
    ticket.className = 'ticket';
    const hasUrl = !!p.url.trim();
    ticket.innerHTML = `
      <div class="order">${i+1}</div>
      <div>
        ${hasUrl
          ? `<a class="name-link" href="${escapeAttr(p.url.trim())}" target="_blank" rel="noopener">${escapeHtml(p.name)}</a>`
          : `<span class="name-link" style="text-decoration:none;">${escapeHtml(p.name)}</span>`}
        ${hasUrl ? `<span class="url-sub">${escapeHtml(p.url.trim())}</span>` : `<span class="url-sub">リンク未入力</span>`}
      </div>
      <button class="copy-btn" data-name="${escapeAttr(p.name)}" data-url="${escapeAttr(p.url.trim())}">コピー</button>
    `;
    grid.appendChild(ticket);
  });

  grid.querySelectorAll('.copy-btn').forEach(btn => {
    btn.addEventListener('click', () => copyLinkedName(btn));
  });
}

/* ---------- リンク付きテキストのコピー ---------- */
async function copyLinkedName(btn){
  const name = btn.dataset.name;
  const url = btn.dataset.url;
  const html = url
    ? `<a href="${url}">${escapeHtml(name)}</a>`
    : escapeHtml(name);
  const plain = name;

  try{
    if(navigator.clipboard && window.ClipboardItem){
      const item = new ClipboardItem({
        'text/html': new Blob([html], {type:'text/html'}),
        'text/plain': new Blob([plain], {type:'text/plain'})
      });
      await navigator.clipboard.write([item]);
    } else {
      await navigator.clipboard.writeText(plain);
    }
    flashDone(btn);
  }catch(e){
    try{
      await navigator.clipboard.writeText(plain);
      flashDone(btn);
      showToast('リンクなしでコピーしました（このブラウザはリンク貼付け非対応）');
    }catch(e2){
      showToast('コピーに失敗しました。手動で選択してコピーしてください');
    }
  }
}

function flashDone(btn){
  const original = btn.textContent;
  btn.textContent = 'コピー済';
  btn.classList.add('done');
  setTimeout(()=>{
    btn.textContent = original;
    btn.classList.remove('done');
  }, 1400);
}

async function copyPlain(text, btn){
  try{
    await navigator.clipboard.writeText(text);
    flashDone(btn);
  }catch(e){
    showToast('コピーに失敗しました');
  }
}

/* ---------- 一括貼り付け ---------- */
function parseBulk(text){
  return text.split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      const parts = line.split('\t').length > 1
        ? line.split('\t')
        : line.split(/\s+(?=https?:\/\/)/);
      const name = (parts[0]||'').trim();
      const url = (parts[1]||'').trim();
      return newRow(name, url);
    })
    .filter(p => p.name);
}

/* ---------- 保存（前回の出演者リストを復元） ---------- */
async function persist(){
  try{
    await window.storage.set(STORAGE_KEY, JSON.stringify(
      performers.map(p => ({name:p.name, url:p.url}))
    ), false);
  }catch(e){
    /* 保存に失敗しても入力自体は継続できるので無視 */
  }
}

async function restore(){
  const statusEl = document.getElementById('saveStatus');
  try{
    const res = await window.storage.get(STORAGE_KEY, false);
    if(res && res.value){
      const arr = JSON.parse(res.value);
      if(Array.isArray(arr) && arr.length){
        performers = arr.map(p => newRow(p.name, p.url));
        statusEl.textContent = '前回の出演者リストを読み込みました。名前を入れ替えて使ってください。';
        return;
      }
    }
    statusEl.textContent = '';
  }catch(e){
    statusEl.textContent = '';
  }
  if(performers.length === 0){
    performers = [newRow(), newRow(), newRow()];
  }
}

/* ---------- イベント ---------- */
document.getElementById('addRowBtn').addEventListener('click', () => {
  performers.push(newRow());
  renderPerformerList();
  renderOutputs();
  persist();
});

document.getElementById('eventDate').addEventListener('input', renderOutputs);
document.getElementById('formDesc').addEventListener('input', renderOutputs);

document.getElementById('bulkToggle').addEventListener('click', () => {
  document.getElementById('bulkBox').classList.toggle('open');
});

document.getElementById('bulkApplyBtn').addEventListener('click', () => {
  const text = document.getElementById('bulkInput').value;
  const rows = parseBulk(text);
  if(rows.length === 0){
    showToast('読み取れる行がありませんでした');
    return;
  }
  performers = performers.filter(p => p.name.trim() || p.url.trim());
  performers = performers.concat(rows);
  document.getElementById('bulkInput').value = '';
  document.getElementById('bulkBox').classList.remove('open');
  renderPerformerList();
  renderOutputs();
  persist();
  showToast(`${rows.length}組を追加しました`);
});

document.getElementById('copyTitleBtn').addEventListener('click', (e) => {
  copyPlain(document.getElementById('outTitle').textContent, e.currentTarget);
});
document.getElementById('copyDescBtn').addEventListener('click', (e) => {
  copyPlain(document.getElementById('outDesc').textContent, e.currentTarget);
});

/* ---------- 初期化 ---------- */
(async function init(){
  await restore();
  renderPerformerList();
  renderOutputs();
})();
</script>

</body>
</html>
