<body>

<div class="wrap">

  <header class="hero">
    <div class="eyebrow">NETAMISE FORM MAKER</div>
    <h1>ネタ見せちゃん<br>フォーム作成</h1>
    <p>タイトル・説明文・出演者リストを入れて「フォームを作成」を押すだけ。コピペ不要で、その場でGoogleフォームが出来上がります。</p>
  </header>

  <section>
    <div class="section-label"><span class="num">01</span><h2>タイトルと説明文</h2></div>
    <div class="card">
      <div class="row-2">
        <div class="field">
          <label class="field-label">開催日</label>
          <input type="text" id="eventDate" placeholder="例：6/21">
        </div>
        <div class="field">
          <label class="field-label">フォーム名（自動）</label>
          <input type="text" id="formTitle" readonly>
        </div>
      </div>
      <div class="field">
        <label class="field-label">説明文</label>
        <textarea id="formDesc">🔥7月ライブのネタ見せ🔥
アドバイス・感想・意見など、なんでも気軽に書いてください！！一言だけでも大歓迎です！！</textarea>
      </div>
    </div>
  </section>

  <section>
    <div class="section-label">
      <span class="num">02</span><h2>出演者リスト</h2>
      <span class="desc">名前とYouTubeリンク</span>
    </div>
    <div class="card">
      <div class="performer-list" id="performerList"></div>
      <div class="list-actions">
        <button class="btn btn-ghost" id="addRowBtn">＋ 1組追加</button>
      </div>
      <button class="bulk-toggle" id="bulkToggle">スプレッドシートなどから一括貼り付け</button>
      <div class="bulk-box" id="bulkBox">
        <p class="bulk-hint">1行＝1組。「名前　URL」をタブまたは半角スペースで区切ってください。</p>
        <textarea id="bulkInput" placeholder="残機	https://youtu.be/vES7yc-A91s
ブラジャー	https://youtu.be/OEY_xaBqD3g"></textarea>
        <div class="list-actions" style="margin-top:10px;">
          <button class="btn btn-primary" id="bulkApplyBtn">リストに反映</button>
        </div>
      </div>
    </div>
  </section>

  <section>
    <div class="section-label"><span class="num">03</span><h2>作成</h2></div>
    <div class="card">
      <div class="create-bar">
        <button class="btn btn-primary" id="createBtn">フォームを作成</button>
        <span class="status-line" id="statusLine"></span>
      </div>
    </div>
  </section>

  <section>
    <div class="result-card" id="resultCard">
      <p class="result-title" id="resultTitle"></p>
      <p class="result-sub">フォームができました。出演者への共有は「回答用リンク」、内容の確認・微調整は「編集する」から。</p>
      <div class="result-links">
        <a href="#" id="viewLink" target="_blank">回答用リンクを開く</a>
        <a href="#" id="editLink" target="_blank" class="secondary">編集する</a>
      </div>
    </div>
  </section>

  <section>
    <button class="setup-toggle" id="setupToggle">このアプリのセットアップについて</button>
    <p class="setup-note" id="setupNote">
      このアプリはGoogle Apps Script上で動いています。実行すると、あなたのGoogleアカウントでGoogleフォームを作成する権限の確認画面が出ます。許可すると、作成したフォームはあなたのGoogle Driveに保存されます。
    </p>
  </section>

</div>

<script>
let performers = [];
let idSeed = 0;

function newRow(name, url){
  return { id: 'p' + (idSeed++), name: name || '', url: url || '' };
}

function pad(n){ return n < 10 ? '0' + n : '' + n; }

function todayLabel(){
  const d = new Date();
  return (d.getMonth() + 1) + '/' + d.getDate();
}

function escapeAttr(s){
  return (s || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;');
}

function renderPerformerList(){
  const wrap = document.getElementById('performerList');
  wrap.innerHTML = '';
  performers.forEach((p, i) => {
    const row = document.createElement('div');
    row.className = 'performer-row';
    row.innerHTML =
      '<div class="order">' + (i + 1) + '</div>' +
      '<input type="text" placeholder="名前" data-field="name" value="' + escapeAttr(p.name) + '">' +
      '<input type="text" placeholder="https://youtu.be/..." data-field="url" value="' + escapeAttr(p.url) + '">' +
      '<button class="icon-btn" data-action="remove" title="削除">×</button>';
    row.querySelectorAll('input').forEach(inp => {
      inp.addEventListener('input', () => {
        p[inp.dataset.field] = inp.value;
      });
    });
    row.querySelector('[data-action=remove]').addEventListener('click', () => {
      performers = performers.filter(x => x.id !== p.id);
      renderPerformerList();
    });
    wrap.appendChild(row);
  });
}

function renderTitlePreview(){
  const date = document.getElementById('eventDate').value.trim();
  const title = date ? (date + ' ネタ見せちゃん') : '';
  document.getElementById('formTitle').value = title;
}

function parseBulk(text){
  return text.split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      const parts = line.indexOf('\t') >= 0
        ? line.split('\t')
        : line.split(/\s+(?=https?:\/\/)/);
      return newRow((parts[0] || '').trim(), (parts[1] || '').trim());
    })
    .filter(p => p.name);
}

function setStatus(msg, isError){
  const el = document.getElementById('statusLine');
  el.textContent = msg || '';
  el.classList.toggle('error', !!isError);
}

function setCreating(isCreating){
  const btn = document.getElementById('createBtn');
  btn.disabled = isCreating;
  btn.innerHTML = isCreating
    ? '<span class="spinner"></span> 作成中…'
    : 'フォームを作成';
}

document.getElementById('addRowBtn').addEventListener('click', () => {
  performers.push(newRow());
  renderPerformerList();
});

document.getElementById('eventDate').addEventListener('input', renderTitlePreview);

document.getElementById('bulkToggle').addEventListener('click', () => {
  document.getElementById('bulkBox').classList.toggle('open');
});

document.getElementById('bulkApplyBtn').addEventListener('click', () => {
  const rows = parseBulk(document.getElementById('bulkInput').value);
  if (rows.length === 0){ setStatus('読み取れる行がありませんでした', true); return; }
  performers = performers.filter(p => p.name.trim() || p.url.trim()).concat(rows);
  document.getElementById('bulkInput').value = '';
  document.getElementById('bulkBox').classList.remove('open');
  renderPerformerList();
  setStatus(rows.length + '組を追加しました');
});

document.getElementById('setupToggle').addEventListener('click', () => {
  document.getElementById('setupNote').classList.toggle('open');
});

document.getElementById('createBtn').addEventListener('click', () => {
  const title = document.getElementById('formTitle').value.trim();
  const description = document.getElementById('formDesc').value;
  const validPerformers = performers
    .filter(p => p.name.trim())
    .map(p => ({ name: p.name.trim(), url: p.url.trim() }));

  if (!title){ setStatus('開催日を入力してください', true); return; }
  if (validPerformers.length === 0){ setStatus('出演者を1組以上入力してください', true); return; }

  setCreating(true);
  setStatus('Googleフォームを作成しています…');

  google.script.run
    .withSuccessHandler(function (res) {
      setCreating(false);
      setStatus('');
      document.getElementById('resultTitle').textContent = res.title + ' を作成しました';
      document.getElementById('viewLink').href = res.viewUrl;
      document.getElementById('editLink').href = res.editUrl;
      document.getElementById('resultCard').classList.add('show');
      document.getElementById('resultCard').scrollIntoView({ behavior: 'smooth', block: 'start' });
    })
    .withFailureHandler(function (err) {
      setCreating(false);
      setStatus((err && err.message) || '作成に失敗しました', true);
    })
    .createNetamiseForm({ title: title, description: description, performers: validPerformers });
});

/* 初期化：日付を自動入力し、前回の出演者リストを読み込む */
(function init(){
  document.getElementById('eventDate').value = todayLabel();
  renderTitlePreview();

  google.script.run
    .withSuccessHandler(function (saved) {
      if (saved && saved.length){
        performers = saved.map(p => newRow(p.name, p.url));
      } else {
        performers = [newRow(), newRow(), newRow()];
      }
      renderPerformerList();
    })
    .withFailureHandler(function () {
      performers = [newRow(), newRow(), newRow()];
      renderPerformerList();
    })
    .loadLastPerformers();
})();
</script>

</body>
</html>
