}
.icon-btn:hover{border-color:var(--vermilion);color:var(--vermilion);background:rgba(232,93,76,0.08);}

.list-actions{display:flex;gap:10px;flex-wrap:wrap;}
button{font-family:"Zen Kaku Gothic New", sans-serif;cursor:pointer;border:none;}
.btn{padding:10px 18px;border-radius:8px;font-size:13.5px;font-weight:500;}
.btn-ghost{background:transparent;border:1px solid rgba(245,239,230,0.22);color:var(--paper-soft);}
