.bulk-toggle{font-size:12.5px;color:var(--grey);background:none;text-decoration:underline;padding:4px 0;margin-top:4px;}
.bulk-toggle:hover{color:var(--spot);}
.bulk-box{margin-top:12px;display:none;}
.bulk-box.open{display:block;}
.bulk-box textarea{font-size:13px;min-height:100px;}
.bulk-hint{font-size:11.5px;color:var(--grey);margin:6px 0 10px;}

.create-bar{
  display:flex;align-items:center;gap:14px;flex-wrap:wrap;
}
.status-line{font-size:12.5px;color:var(--grey);}
.status-line.error{color:var(--vermilion);}

.result-card{
  background:var(--paper);color:var(--ink);border-radius:12px;padding:20px 22px;
  display:none;
}
.result-card.show{display:block;}
.result-card .result-title{
