}
.result-card .result-sub{font-size:12.5px;color:var(--grey);margin:0 0 16px;}
.result-links{display:flex;gap:10px;flex-wrap:wrap;}
.result-links a{
  display:inline-flex;align-items:center;gap:6px;
  background:var(--ink);color:var(--paper);
  padding:9px 16px;border-radius:7px;
  font-size:13px;text-decoration:none;
}
.result-links a.secondary{background:transparent;color:var(--ink);border:1px solid rgba(22,21,26,0.25);}
.folder-warning{
  font-size:12px;color:var(--vermilion);margin:14px 0 0;display:none;
}
.folder-warning.show{display:block;}

.spinner{
  width:14px;height:14px;border-radius:50%;
  border:2px solid rgba(22,21,26,0.25);border-top-color:var(--ink);
  animation:spin .7s linear infinite;display:inline-block;
}
@keyframes spin{to{transform:rotate(360deg);}}

.setup-toggle{
  font-size:12px;color:var(--grey);text-decoration:underline;background:none;padding:0;
}
.setup-toggle:hover{color:var(--spot);}
.setup-note{
  font-size:12.5px;color:var(--paper-soft);opacity:0.8;margin-top:10px;display:none;
}
.setup-note.open{display:block;}

::placeholder{color:rgba(245,239,230,0.3);}

