<style>
  :root{
    --ink:#2B2640;
    --ink-soft:rgba(43,38,64,0.6);
    --paper:#FAF9FF;
    --violet:#6C4DE6;
    --violet-deep:#5638C2;
    --coral:#E8604A;
    --green:#2DA875;
    --line:rgba(43,38,64,0.12);
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    background:var(--paper);
    color:var(--ink);
    font-family:"Zen Kaku Gothic New", sans-serif;
    min-height:100vh;
    line-height:1.6;
  }
  .wrap{
    max-width:720px;
    margin:0 auto;
    padding:40px 22px 100px;
  }
  header.hero{
    padding:4px 0 28px;
    border-bottom:1px solid var(--line);
    margin-bottom:34px;
  }
  .eyebrow{
    display:inline-flex;align-items:center;gap:6px;
    font-family:"Zen Maru Gothic", sans-serif;
    font-weight:700;
    font-size:12px;
    color:#fff;
    background:var(--violet);
    padding:5px 14px;
    border-radius:999px;
    margin-bottom:16px;
  }
  h1{
    font-family:"Zen Maru Gothic", sans-serif;
    font-weight:700;
    font-size:clamp(24px,4.6vw,32px);
    margin:0 0 12px;
    color:var(--ink);
  }
  h1 .accent{ color:var(--violet); }
  header.hero p{
    color:var(--ink-soft);font-size:14px;margin:0;max-width:520px;
  }

  section{margin-bottom:36px;}
  .section-label{display:flex;align-items:center;gap:10px;margin-bottom:16px;}
  .section-label .num{
    display:inline-flex;align-items:center;justify-content:center;
    width:26px;height:26px;border-radius:50%;flex-shrink:0;
    font-family:"Zen Maru Gothic", sans-serif;font-weight:700;font-size:12.5px;
    color:#fff;
  }
  .num-1{background:var(--violet);}
  .num-2{background:var(--coral);}
  .num-3{background:var(--green);}
  .section-label h2{font-family:"Zen Maru Gothic", sans-serif;font-size:17px;font-weight:700;margin:0;color:var(--ink);}
  .section-label .desc{font-size:12px;color:var(--ink-soft);margin-left:auto;}

  .card{
    background:#fff;
    border:1px solid var(--line);
    border-radius:16px;
    padding:22px;
    box-shadow:0 1px 2px rgba(43,38,64,0.04), 0 4px 14px rgba(43,38,64,0.05);
  }

  label.field-label{font-family:"Zen Kaku Gothic New", sans-serif;font-weight:700;font-size:12.5px;color:var(--violet-deep);margin-bottom:7px;display:block;}

  input[type=text], input[type=url], textarea{
    width:100%;
    background:var(--paper);
    border:1px solid var(--line);
    border-radius:10px;
    color:var(--ink);
    font-family:"Zen Kaku Gothic New", sans-serif;
    font-size:14.5px;
    padding:11px 13px;
  }
  input:focus, textarea:focus{
    outline:none;border-color:var(--violet);background:#fff;
    box-shadow:0 0 0 3px rgba(108,77,230,0.14);
  }
  textarea{resize:vertical;min-height:80px;line-height:1.7;}

  .field{margin-bottom:16px;}
  .field:last-child{margin-bottom:0;}
  .row-2{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
  @media (max-width:560px){ .row-2{grid-template-columns:1fr;} }

  .performer-list{display:flex;flex-direction:column;gap:10px;margin-bottom:14px;}
  .performer-row{
    display:grid;
    grid-template-columns:26px 1.1fr 1fr 32px;
    gap:9px;align-items:start;
    background:#fff;
    border:1px solid var(--line);
    border-radius:12px;
    padding:10px 10px;
  }
  @media (max-width:560px){
    .performer-row{grid-template-columns:26px 1fr 32px;}
    .performer-row .name-cell{grid-column:2 / 3;margin-top:7px;}
  }
  .performer-row .order{
    font-family:"Zen Maru Gothic", sans-serif;font-weight:700;color:var(--ink-soft);font-size:13px;
    text-align:center;padding-top:9px;
  }
  .performer-row input{padding:9px 11px;font-size:13.5px;}
  .name-cell{display:flex;flex-direction:column;gap:4px;}
  .name-cell input{
    font-family:"Zen Maru Gothic", sans-serif;font-weight:700;font-size:14px;
  }
  .name-status{
    font-size:10.5px;color:var(--ink-soft);padding-left:2px;min-height:13px;
    display:flex;align-items:center;gap:5px;
  }
  .name-status.error{color:var(--coral);}
  .name-status .mini-spinner{
    width:9px;height:9px;border-radius:50%;
    border:1.5px solid rgba(43,38,64,0.2);border-top-color:var(--violet);
    animation:spin .7s linear infinite;display:inline-block;
  }
  .icon-btn{
    width:30px;height:30px;border-radius:50%;border:1px solid var(--line);
    background:#fff;color:var(--ink-soft);cursor:pointer;
    display:flex;align-items:center;justify-content:center;font-size:14px;
  }
  .icon-btn:hover{border-color:var(--coral);color:var(--coral);background:rgba(232,96,74,0.06);}

  .list-actions{display:flex;gap:10px;flex-wrap:wrap;}
  button{font-family:"Zen Kaku Gothic New", sans-serif;cursor:pointer;border:none;}
  .btn{
    padding:10px 20px;border-radius:999px;font-size:13.5px;font-weight:700;
    font-family:"Zen Maru Gothic", sans-serif;
    transition:transform .08s ease, box-shadow .12s ease, background .12s ease;
  }
  .btn-ghost{background:#fff;border:1px solid var(--line);color:var(--ink);}
  .btn-ghost:hover{border-color:var(--violet);color:var(--violet-deep);}
  .btn-primary{
    background:var(--violet);color:#fff;border:none;
    box-shadow:0 2px 8px rgba(108,77,230,0.35);
  }
  .btn-primary:hover{background:var(--violet-deep);box-shadow:0 3px 10px rgba(108,77,230,0.4);}
  .btn-primary:active{transform:translateY(1px);box-shadow:0 1px 4px rgba(108,77,230,0.35);}
  .btn-primary:disabled{opacity:0.5;cursor:not-allowed;box-shadow:none;transform:none;}
  #createBtn{padding:13px 28px;font-size:14.5px;}

  .bulk-toggle{font-size:12.5px;color:var(--violet);font-weight:700;background:none;text-decoration:underline;padding:4px 0;margin-top:4px;}
  .bulk-toggle:hover{color:var(--violet-deep);}
