  1	/**
  2	 * ネタ見せちゃん フォーム自動作成
  3	 * ------------------------------------------------------
  4	 * Webアプリとして開いたときの入口
  5	 */
  6	function doGet() {
  7	  return HtmlService.createHtmlOutputFromFile('index')
  8	    .setTitle('ネタ見せちゃん フォーム作成')
  9	    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
 10	    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
 11	}
 12	
 13	/**
 14	 * 前回入力した出演者リストを取得する（自分のGoogleアカウントごとに保存される）
 15	 */
 16	function loadLastPerformers() {
 17	  const props = PropertiesService.getUserProperties();
 18	  const raw = props.getProperty('NETAMISE_LAST_PERFORMERS');
 19	  if (!raw) return [];
 20	  try {
 21	    return JSON.parse(raw);
 22	  } catch (e) {
 23	    return [];
 24	  }
 25	}
 26	
 27	/**
 28	 * 出演者リストを保存する
 29	 */
 30	function saveLastPerformers_(performers) {
 31	  const props = PropertiesService.getUserProperties();
 32	  props.setProperty('NETAMISE_LAST_PERFORMERS', JSON.stringify(performers));
 33	}
 34	
 35	/**
 36	 * YouTubeのURLから動画タイトル（＝出演者名として使う）を取得する
 37	 * urls: string[]
 38	 * 戻り値: [{ url, title, error }]
 39	 */
 40	function fetchYoutubeTitles(urls) {
 41	  return (urls || []).map(function (url) {
 42	    const trimmed = (url || '').trim();
 43	    if (!trimmed) {
 44	      return { url: trimmed, title: '', error: 'URLが空です' };
 45	    }
 46	    try {
 47	      const oembedUrl = 'https://www.youtube.com/oembed?url=' + encodeURIComponent(trimmed) + '&format=json';
 48	      const res = UrlFetchApp.fetch(oembedUrl, { muteHttpExceptions: true });
 49	      if (res.getResponseCode() !== 200) {
 50	        return { url: trimmed, title: '', error: 'タイトルを取得できませんでした（URLを確認してください）' };
 51	      }
 52	      const data = JSON.parse(res.getContentText());
 53	      return { url: trimmed, title: data.title || '', error: null };
 54	    } catch (e) {
 55	      return { url: trimmed, title: '', error: 'タイトルを取得できませんでした（URLを確認してください）' };
 56	    }
 57	  });
 58	}
 59	
 60	/**
 61	 * 権限確認専用：Driveへのアクセス権限をその場で許可させるためだけの関数。
 62	 * エディタの関数選択でこれを選び、「実行」を押すと権限確認画面が出ます。
 63	 */
 64	function authorizeDriveAccess() {
 65	  const folder = getOrCreateNetamiseFolder_();
 66	  console.log('OK: ' + folder.getName());
 67	}
 68	
 69	/**
 70	 * 「ネタ見せちゃん」フォルダを取得する（なければ作成する）
 71	 */
 72	function getOrCreateNetamiseFolder_() {
 73	  const FOLDER_NAME = 'ネタ見せちゃん';
 74	  const folders = DriveApp.getFoldersByName(FOLDER_NAME);
 75	  if (folders.hasNext()) {
 76	    return folders.next();
 77	  }
 78	  return DriveApp.createFolder(FOLDER_NAME);
 79	}
 80	
 81	/**
 82	 * メイン処理：フォームを実際に作成する
 83	 * payload = { title: string, description: string, performers: [{name, url}] }
 84	 * 戻り値 = { editUrl, viewUrl, title }
 85	 */
 86	function createNetamiseForm(payload) {
 87	  const title = (payload && payload.title || '').trim();
 88	  const description = (payload && payload.description || '').trim();
 89	  const performers = (payload && payload.performers || []).filter(function (p) {
 90	    return p && p.name && p.name.trim();
 91	  });
 92	
 93	  if (!title) {
 94	    throw new Error('フォームのタイトルが空です。開催日を入力してください。');
 95	  }
 96	  if (performers.length === 0) {
 97	    throw new Error('出演者が1組も入力されていません。');
 98	  }
 99	
100	  let step = '初期化';
101	  try {
102	    // 1. フォーム本体を作成
103	    step = 'フォームの作成（FormApp.create）';
104	    const form = FormApp.create(title);
105	
106	    step = '説明文の設定';
107	    form.setDescription(description);
108	
109	    step = 'ログイン要件の設定';
110	    try { form.setRequireLogin(false); } catch (e) { /* 個人アカウントでは無視してよい */ }
111	
112	    step = 'メール収集設定';
113	    try { form.setCollectEmail(false); } catch (e) { /* 個人アカウントでは無視してよい */ }
114	
115	    // 2. 出演者ごとに項目を追加
116	    performers.forEach(function (p) {
117	      const name = p.name.trim();
118	      const url = (p.url || '').trim();
119	
120	      step = '「' + name + '」の動画項目を追加';
121	      try {
122	        if (url) {
123	          const videoItem = form.addVideoItem();
124	          videoItem.setTitle(name);
125	          videoItem.setVideoUrl(url);
126	          videoItem.setAlignment(FormApp.Alignment.CENTER);
127	          videoItem.setWidth(640);
128	        } else {
129	          form.addSectionHeaderItem().setTitle(name);
130	        }
131	      } catch (e) {
132	        // 動画として追加できない場合は、見出し＋URLのテキストに切り替えて続行する
133	        form.addSectionHeaderItem()
134	          .setTitle(name)
135	          .setHelpText(url ? ('動画リンク：' + url) : '');
136	      }
137	
138	      step = '「' + name + '」の感想欄を追加';
139	      form.addParagraphTextItem()
140	        .setTitle('「' + name + '」へのコメント')
141	        .setRequired(false);
142	    });
143	
144	    // 3. 次回のために出演者リストを保存
145	    step = '出演者リストの保存';
146	    try { saveLastPerformers_(performers); } catch (e) { /* 保存に失敗しても作成自体は続行する */ }
147	
148	    step = 'フォルダへの移動';
149	    let folderMoveError = null;
150	    try {
151	      const folder = getOrCreateNetamiseFolder_();
152	      DriveApp.getFileById(form.getId()).moveTo(folder);
153	    } catch (e) {
154	      // フォーム自体は作成済みなので処理は止めず、理由だけ持っておいて後で表示する
155	      folderMoveError = (e && e.message) ? e.message : String(e);
156	    }
157	
158	    step = 'URLの取得';
159	    const result = {
160	      editUrl: form.getEditUrl(),
161	      viewUrl: form.getPublishedUrl(),
162	      title: title,
163	      folderMoveError: folderMoveError
164	    };
165	
166	    return result;
167	
168	  } catch (e) {
169	    // どの段階で失敗したかをそのままエラーメッセージに含めて返す
170	    throw new Error('「' + step + '」の処理で失敗しました： ' + (e && e.message ? e.message : e));
171	  }
172	}
