/* 開催日欄（例：6/30、12/3）を告知用の4桁表記（0630、1203）に変換する */
function dateToCompact(dateStr){
  const m = (dateStr || '').match(/(\d{1,2})\s*\/\s*(\d{1,2})/);
  if (!m) return (dateStr || '').trim();
  const mm = ('0' + m[1]).slice(-2);
  const dd = ('0' + m[2]).slice(-2);
  return mm + dd;
}

/* グループLINE用の告知文を組み立てる */
function buildAnnounceText(formUrl){
  const compact = dateToCompact(document.getElementById('eventDate').value);
  let text = compact + 'ネタ見せちゃんの動画が公開されました！🙌\n'
    + 'フォームから感想・意見・アドバイスなど受け付けてます！！\n'
    + 'お願いします！！！(お願いします)\n'
    + '【フォーム】\n'
    + formUrl;
  if (lastPlaylistUrl) {
    text += '\n【再生リスト】\n' + lastPlaylistUrl;
  }
  return text;
}

document.getElementById('announceCopyBtn').addEventListener('click', async () => {
  const btn = document.getElementById('announceCopyBtn');
  const text = document.getElementById('announceText').value;
  try{
    await navigator.clipboard.writeText(text);
  }catch(e){
    // 一部の環境でclipboard APIが使えない場合の代替
    const ta = document.getElementById('announceText');
    ta.select();
    document.execCommand('copy');
  }
  const original = btn.textContent;
  btn.textContent = 'コピー済み';
  btn.classList.add('done');
  setTimeout(() => {
    btn.textContent = original;
    btn.classList.remove('done');
  }, 1400);
});

document.getElementById('createBtn').addEventListener('click', () => {
  const title = document.getElementById('formTitle').value.trim();
  const description = document.getElementById('formDesc').value;
  const validPerformers = performers
    .filter(p => p.name.trim())
    .map(p => ({ name: p.name.trim(), url: p.url.trim() }));

  if (!title){ setStatus('開催日を入力してください', true); return; }
  if (validPerformers.length === 0){ setStatus('出演者を1組以上入力してください', true); return; }

  setCreating(true);
  setStatus('Googleフォームを作成しています…');

  google.script.run
    .withSuccessHandler(function (res) {
      setCreating(false);
      setStatus('');
      document.getElementById('resultTitle').textContent = '🎉 ' + res.title + ' を作成しました';
      document.getElementById('viewLink').href = res.viewUrl;
      document.getElementById('editLink').href = res.editUrl;
      document.getElementById('announceText').value = buildAnnounceText(res.viewUrl);
      const warningEl = document.getElementById('folderWarning');
      if (res.folderMoveError) {
        warningEl.textContent = '「ネタ見せちゃん」フォルダへの移動はできませんでした： ' + res.folderMoveError;
        warningEl.classList.add('show');
      } else {
        warningEl.classList.remove('show');
      }
      document.getElementById('resultCard').classList.add('show');
      document.getElementById('resultCard').scrollIntoView({ behavior: 'smooth', block: 'start' });
    })
    .withFailureHandler(function (err) {
      setCreating(false);
      setStatus((err && err.message) || '作成に失敗しました', true);
    })
    .createNetamiseForm({ title: title, description: description, performers: validPerformers });
});

