    console.log('NG（Drive）： ' + (e && e.message ? e.message : e));
  }

  // --- YouTube Data API（再生リスト一括取り込み機能） ---
  try {
    const response = YouTube.PlaylistItems.list('snippet', {
      playlistId: 'PLOU2XLYxmsIKpaV8h0AGE05so0fAwwfTw',
      maxResults: 1
    });
    const title = (response && response.items && response.items[0])
      ? response.items[0].snippet.title
