const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel,
  PageNumber, Header, Footer, TableOfContents, ExternalHyperlink,
  BorderStyle,
} = require('docx');
const {
  h1, h2, h3, p, pRich, leadIn, bullets, numbered,
  pointBox, warningBox, spacer, screenshotPlaceholder, codeBlock,
  dataTable, pageBreak,
} = require('./helpers.js');

function link(text, url) {
  return new ExternalHyperlink({
    children: [new TextRun({ text, style: 'Hyperlink' })],
    link: url,
  });
}

// ============================================================
// TITLE PAGE
// ============================================================
const titlePage = [
  new Paragraph({ spacing: { before: 2400 }, children: [] }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: '動画編集マニュアル', size: 56, bold: true })],
  }),
  new Paragraph({
    spacing: { before: 240 },
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: '〜お笑いサークル編集部 本編・オープニング編集ガイド〜', size: 28 })],
  }),
  new Paragraph({
    spacing: { before: 800 },
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: '対応ソフト：Adobe Premiere Pro / DaVinci Resolve', size: 24, color: '555555' })],
  }),
  new Paragraph({ children: [new (require('docx').PageBreak)()] }),
];

// ============================================================
// PART 0: はじめに
// ============================================================
const part0 = [
  h1('Part 0：はじめに'),

  h2('0-1. このマニュアルの目的'),
  p('このマニュアルは、学内・学外で行われたお笑いライブの映像を編集し、YouTubeに公開するための手順をまとめたものです。'),
  p('編集部で行う作業は、大きく分けて以下の2つです。'),
  numbered([
    { bold: '①オープニング映像の編集：', text: '本編に出演する演者の紹介（名前・写真など）' },
    { bold: '②本編の編集：', text: 'お笑いライブ本編の映像を、見やすく・聞きやすく整える編集' },
  ]),
  p('この2つの映像をつなぎ合わせ、最終的にYouTubeへアップロードするところまでが、編集部の一連の作業となります。'),
  p('このマニュアルでは、Adobe Premiere ProとDaVinci Resolveという2つの動画編集ソフトを使った編集方法を、どちらも同じ流れで解説します。自分が使うソフトのパートだけを読み進めれば、一通りの作業ができるようになります。'),

  h2('0-2. どちらのソフトを使う？'),
  p('編集部では、編集の頻度や好みに応じて、以下の方針でソフトを選んでください。'),
  dataTable(
    ['', 'Adobe Premiere Pro', 'DaVinci Resolve'],
    [
      ['料金', '有料（後述の学割あり）', '無料'],
      ['こんな人におすすめ', '編集部の活動でガシガシ編集していきたい人、将来的に動画編集を仕事や趣味として続けたい人', 'たまにしか編集しない人、まずはお金をかけずに試したい人'],
      ['特徴', '業界標準ソフトで知名度が高く、調べれば情報が見つかりやすい。解説動画も豊富', '無料版でも本編編集に必要な機能はほぼ揃っている。色調補正（カラーグレーディング）の機能は特に強力'],
    ],
    [1800, 3613, 3613]
  ),
  spacer(),
  p('どちらを選んでも、このマニュアルで解説する編集（音量調整・暗転処理・カット＋トランジションなど）は問題なく行えます。まず無料のDaVinci Resolveで試してみて、編集にもっと力を入れたくなったらPremiere Proに移行する、という進め方もおすすめです。'),

  h2('0-3. 準備するもの'),
  h3('必要な環境'),
  bullets([
    'Windows または Mac のパソコン（編集作業用）',
    'インターネット接続',
    '編集する元の映像データ・音声データ',
  ]),

  h3('Adobe Premiere Proを使う場合'),
  leadIn('① 千葉大学の学生・教職員向け割引（学割）を使う', ''),
  p('千葉大学生協では、千葉大生限定の特別価格でAdobe Creative Cloudを購入できるプログラムを提供しています。登録には千葉大学から付与されたメールアドレス（@chiba-u.jp）が必要で、Gmailなどでは登録できません。また、手続きには学生証または在学証明書の提示が必要です。'),
  pointBox('詳細・最新の価格・申し込み方法は、千葉大学生協の公式ページで必ず確認してください（価格は変更される場合があります）。'),
  pRich([link('千葉大学生協：AdobeCC千葉大生版のご案内', 'https://www.univcoop.jp/chiba-u/news_4/news_detail_208105.html')]),

  leadIn('② インストール手順を詳しく知りたい場合', ''),
  p('以下のサイトが、アカウント作成からインストールまでを画面付きで分かりやすく解説しています。'),
  bullets([
    { bold: '', text: 'エディタハブ「初心者必見！Premiere Proの始め方ガイド」：https://hub.editorguard.com/posts/premiere-pro-1751464206354' },
    { bold: '', text: 'LIG「初心者向け Premiere Proの使い方」：https://liginc.co.jp/645951' },
