        {
            await ModelLoaderClient.Instance.LoadModels(MyPrefs.ModelPaths);
            MyEvents.MainSceneOpened?.Invoke(gameObject);
            StartCoroutine(LoadSceneCoroutine(MyPrefs.MainScene));
        }

